	template <class T, class Set>
	int CheckBit(Set set, std::size_t offset, std::uint32_t mask, const char* what, std::string* first)
	{
		std::vector<unsigned char> buffer(sizeof(T), 0);
		set(*reinterpret_cast<T*>(buffer.data()));
		std::uint32_t v = 0;
		std::memcpy(&v, buffer.data() + offset, sizeof v);
		std::size_t set_bytes = 0;
		for (unsigned char b : buffer) set_bytes += b != 0;
		if (v == mask && set_bytes == 1) return 0;
		if (first && first->empty()) *first = what;
		return 1;
	}

